'use strict';
(function(){
const defaultBytes=628125;let sourceBytes=defaultBytes,dialog=null,token=0,timer=0,ready=null;
function bytes(n){if(!Number.isFinite(n)||n<0)return 'неизвестно';if(n<1024)return n+' Б';if(n<1048576)return (n/1024).toLocaleString('ru-RU',{maximumFractionDigits:1})+' КБ';return (n/1048576).toLocaleString('ru-RU',{maximumFractionDigits:2})+' МБ'}
const beforeSource=applySource;applySource=function(image,...args){const value=beforeSource(image,...args);sourceBytes=image.fragmentSourceBytes??(args[0]==='CLUB ENDURO LENINGRADSKAYA'?defaultBytes:null);if(dialog?.open)schedule();return value};
const beforeLoad=loadImg;loadImg=async function(src){const image=await beforeLoad(src);if(src==='assets/enduro-logo.png')image.fragmentSourceBytes=defaultBytes;else if(/^(blob:|data:)/.test(src))try{image.fragmentSourceBytes=(await(await fetch(src)).blob()).size}catch{}return image};
for(const id of ['file','projectFile']){const input=$(id),handler=input.onchange;input.onchange=async function(e){const file=e.target.files[0],previous=base;await handler.call(this,e);if(file&&base!==previous)sourceBytes=file.size}}
function project(){return new Blob([JSON.stringify({version:1,name:$('filename').textContent,base:base.toDataURL(),visible:$('baseVisible').checked,pending,layers:layers.map(serializeLayer),sourceBytes})],{type:'application/json'})}
$('save').onclick=()=>download(project(),'fragment-project.json');
function alpha(){const a=bc().getImageData(0,0,base.width,base.height).data;for(let i=3;i<a.length;i+=4)if(a[i]<255)return true;return false}
function ensure(){if(dialog)return;dialog=document.createElement('dialog');dialog.className='export-dialog';dialog.setAttribute('aria-labelledby','exportHeading');dialog.innerHTML='<h2 id="exportHeading">Сохранить</h2><div class="export-grid"><label>Формат<select id="exportFormat"><option value="png">PNG</option><option value="jpeg">JPEG</option><option value="webp">WebP</option><option value="svg">SVG · векторизация</option><option value="json">Проект JSON</option></select></label><div class="export-source">Исходный файл<strong id="exportOriginal"></strong></div><label id="exportScaleField">Масштаб экспорта: <span id="exportScaleValue">100%</span><span id="exportDimensions"></span><input id="exportScale" aria-label="Масштаб экспорта" type="range" min="10" max="100" value="100"></label><label id="exportQualityField">Качество: <span id="exportQualityValue">90%</span><input id="exportQuality" aria-label="Качество сжатия" type="range" min="10" max="100" value="90"></label></div><label id="exportTransparencyField" class="export-transparency"><input type="checkbox" id="exportTransparent"> Прозрачный фон</label><div id="svgFields" class="export-grid" hidden><label>Цветов SVG<select id="svgColors"><option value="0" selected>Авто</option><option>2</option><option>8</option><option>16</option><option>32</option></select></label><label>Точность SVG<select id="svgDetail"><option value="512">Обычная</option><option value="1024" selected>Высокая</option><option value="2048">Максимальная</option></select></label></div><p id="exportWarnings" role="status"></p><p id="exportResult" role="status" aria-live="polite"></p><div class="export-actions"><button id="cancelExport">Отмена</button><button id="confirmExport" class="primary">Сохранить файл</button></div>';document.body.append(dialog);
 $('cancelExport').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{if(dialog.open)return;clearTimeout(timer);token++;ready=null});
 for(const id of ['svgColors','svgDetail'])$(id).onchange=schedule;$('exportFormat').onchange=()=>{fields();schedule()};for(const id of ['exportScale','exportQuality'])$(id).oninput=schedule;$('exportTransparent').oninput=()=>{dialog.alphaChoice=$('exportTransparent').checked;schedule()};
 $('confirmExport').onclick=()=>{if(!ready)return;const output=ready;download(output.blob,output.name);dialog.close();toast('Файл сохранён')};}
function fields(){const format=$('exportFormat').value,json=format==='json';$('svgFields').hidden=format!=='svg';$('exportScaleField').hidden=json;$('exportQualityField').hidden=!['jpeg','webp'].includes(format);$('exportTransparencyField').hidden=json;$('exportTransparent').disabled=format==='jpeg'||(!layers.length&&!dialog.hasAlpha);$('exportTransparent').checked=!json&&format!=='jpeg'&&dialog.alphaChoice;$('exportTransparencyField').dataset.tooltip=format==='jpeg'?'JPEG сохраняется на белом фоне.':!layers.length&&!dialog.hasAlpha?'Сначала отделите объекты, чтобы убрать фон.':'Сохранить объекты без исходного фона.'}
function preflight(){const warnings=[],format=$('exportFormat').value,ratio=Number($('exportScale').value)/100;if(format==='json')return warnings;const clipped=layers.filter(l=>l.visible!==false&&(l.opacity??1)>0).filter(l=>{const b=layerBounds(l);return b.x<0||b.y<0||b.x+b.w>base.width||b.y+b.h>base.height}).length;if(clipped)warnings.push('За границами холста: '+clipped+'.');if(format!=='svg'&&Math.min(base.width*ratio,base.height*ratio)<600)warnings.push('Для крупной печати разрешение невелико.');if(format==='jpeg'&&(!$('baseVisible').checked||dialog.hasAlpha||layers.some(l=>l.opacity<1)))warnings.push('JPEG сохранит прозрачность на белом фоне.');if(format==='svg')warnings.push($('svgColors').value==='0'?'SVG автоматически упрощает цвета и контуры.':'SVG упрощает изображение до '+$('svgColors').value+' цветов.');return warnings}
function schedule(){if(!dialog?.open)return;clearTimeout(timer);const request=++token;ready=null;$('confirmExport').disabled=true;$('exportScaleValue').textContent=$('exportScale').value+'%';const ratio=Number($('exportScale').value)/100;$('exportDimensions').textContent=' · '+Math.max(1,Math.round(base.width*ratio))+' × '+Math.max(1,Math.round(base.height*ratio))+' пикс.';$('exportQualityValue').textContent=$('exportQuality').value+'%';$('exportResult').textContent=$('exportFormat').value==='svg'?'Строим векторные контуры…':'Результат: считаем…';$('exportWarnings').textContent=preflight().join(' ');timer=setTimeout(()=>encode(request),160)}
async function encode(request){try{const format=$('exportFormat').value;let blob,name,dimensions='';if(format==='json'){blob=project();name='fragment-project.json'}else{const ratio=Number($('exportScale').value)/100,w=Math.max(1,Math.round(base.width*ratio)),h=Math.max(1,Math.round(base.height*ratio)),image=off(w,h),c=image.getContext('2d'),transparent=format!=='jpeg'&&!$('exportTransparent').disabled&&$('exportTransparent').checked;c.imageSmoothingEnabled=true;c.imageSmoothingQuality='high';if(!transparent){c.fillStyle='#fff';c.fillRect(0,0,w,h)}c.scale(w/base.width,h/base.height);if($('baseVisible').checked&&(!transparent||!layers.length))c.drawImage(base,0,0);layers.forEach(layer=>drawLayer(c,layer));const mime='image/'+format;if(format==='svg'){const result=await FragmentVector.trace(image,{colors:+$('svgColors').value,detail:+$('svgDetail').value});blob=new Blob([result.svg],{type:'image/svg+xml'});name='fragment-logo.svg';dimensions=' · '+result.paths+' контуров'}else{blob=await new Promise(resolve=>image.toBlob(resolve,mime,Number($('exportQuality').value)/100));if(!blob||blob.type!==mime)throw Error('Формат недоступен. Выберите PNG.');name='fragment-logo.'+(format==='jpeg'?'jpg':format);dimensions=' · '+w+' × '+h}}
 if(request!==token||!dialog.open)return;ready={blob,name};$('exportResult').textContent='Результат: '+bytes(blob.size)+dimensions;$('confirmExport').disabled=false;
 }catch(error){if(request!==token)return;$('exportResult').textContent=globalThis.FragmentErrors?.report(error,'Не удалось подготовить файл.')||'Не удалось подготовить файл.'}}
$('export').onclick=()=>{ensure();$('exportOriginal').textContent=bytes(sourceBytes);dialog.hasAlpha=alpha();dialog.alphaChoice=!$('baseVisible').checked||(!layers.length&&dialog.hasAlpha);fields();if(!dialog.open)dialog.showModal();$('exportFormat').focus();schedule()};
window.FragmentExport={preflight,sourceBytes:()=>sourceBytes,setSourceBytes:value=>{sourceBytes=Number.isFinite(value)?value:null},preview:()=>ready?{size:ready.blob.size,name:ready.name,type:ready.blob.type}:null};
})();
